// ============================================================================
// COMPETITOR WATCHLIST & UPFRONT COST CAP
// ============================================================================
const MAX_RUN_BUDGET_USD = 0.50;
const MIN_ENDURANCE_DAYS = 14;

const competitors = [
  { client_account: 'Acme SaaS', competitor_domain: 'monday.com' },
  { client_account: 'Acme SaaS', competitor_domain: 'clickup.com' },
  { client_account: 'Acme SaaS', competitor_domain: 'notion.so' }
];

return competitors.map(c => ({
  json: {
    ...c,
    domain: c.competitor_domain.toLowerCase().trim(),
    min_endurance_days: MIN_ENDURANCE_DAYS,
    max_run_budget_usd: MAX_RUN_BUDGET_USD
  }
}));

// ============================================================================
// 14+ DAYS ENDURANCE & AD DEDUPLICATION ENGINE
// Note: Longevity (14+ days active) is used as a campaign endurance signal,
// not a guaranteed measure of advertiser ROAS.
// ============================================================================
const staticData = $getWorkflowStaticData('global');
if (!staticData.seenAdIds) {
  staticData.seenAdIds = {};
}

const items = $input.all();
const digest = [];

for (const item of items) {
  const row = item.json;
  const domain = String(row.domain || row.competitor_domain || 'unknown');
  const ads = Array.isArray(row.ads) ? row.ads : [];

  const enduringAds = [];
  const newlyLaunchedAds = [];
  let discardedShortTests = 0;

  for (const ad of ads) {
    const adId = String(ad.id || ad.creative_id || ad.ad_id || ad.preview_url || '');
    if (!adId) continue;

    const firstShown = ad.first_shown ? new Date(ad.first_shown).getTime() : Date.now();
    const lastShown = ad.last_shown ? new Date(ad.last_shown).getTime() : Date.now();
    const daysActive = Math.max(1, Math.round((lastShown - firstShown) / (1000 * 60 * 60 * 24)));

    const wasSeenBefore = Boolean(staticData.seenAdIds[adId]);
    staticData.seenAdIds[adId] = { domain, first_tracked: new Date().toISOString(), daysActive };

    if (daysActive >= 14) {
      enduringAds.push({
        ad_id: adId,
        format: ad.format || 'TEXT/IMAGE',
        days_active: daysActive,
        signal_type: 'ENDURING_14_PLUS_DAYS',
        headline: ad.headline || ad.title || 'Active Creative',
        preview_url: ad.preview_url || ad.link || ''
      });
    } else if (!wasSeenBefore) {
      newlyLaunchedAds.push({
        ad_id: adId,
        format: ad.format || 'TEXT/IMAGE',
        days_active: daysActive,
        signal_type: 'NEW_LAUNCH_THIS_WEEK',
        headline: ad.headline || ad.title || 'New Creative',
        preview_url: ad.preview_url || ad.link || ''
      });
    } else {
      discardedShortTests++;
    }
  }

  digest.push({
    json: {
      domain,
      total_ads_scanned: ads.length,
      enduring_14d_ads_count: enduringAds.length,
      new_launches_count: newlyLaunchedAds.length,
      discarded_short_tests: discardedShortTests,
      should_audit_landing_tech: enduringAds.length > 0 || newlyLaunchedAds.length > 0,
      enduring_ads_sample: enduringAds.slice(0, 5),
      new_launches_sample: newlyLaunchedAds.slice(0, 5)
    }
  });
}

return digest;
